css:
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0
}

.relative {
  position: relative
}

.inline-flex {
  display: inline-flex
}

.h-12 {
  height: 3rem
}

.w-24 {
  width: 6rem
}

.cursor-pointer {
  cursor: pointer
}

.items-center {
  align-items: center
}

.rounded-full {
  border-radius: 9999px
}

.bg-gradient-to-r {
  background-image: linear-gradient(to right, var(--tw-gradient-stops))
}

.from-rose-400 {
  --tw-gradient-from: #fb7185 var(--tw-gradient-from-position);
  --tw-gradient-to: rgb(251 113 133 / 0) var(--tw-gradient-to-position);
  --tw-gradient-stops: var(--tw-gradient-from), var(--tw-gradient-to)
}

.to-red-900 {
  --tw-gradient-to: #7f1d1d var(--tw-gradient-to-position)
}

.shadow-md {
  --tw-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  --tw-shadow-colored: 0 4px 6px -1px var(--tw-shadow-color), 0 2px 4px -2px var(--tw-shadow-color);
  box-shadow: var(--tw-ring-offset-shadow, 0 0 #0000), var(--tw-ring-shadow, 0 0 #0000), var(--tw-shadow)
}

.outline-none {
  outline: 2px solid transparent;
  outline-offset: 2px
}

.ring-0 {
  --tw-ring-offset-shadow: var(--tw-ring-inset) 0 0 0 var(--tw-ring-offset-width) var(--tw-ring-offset-color);
  --tw-ring-shadow: var(--tw-ring-inset) 0 0 0 calc(0px + var(--tw-ring-offset-width)) var(--tw-ring-color);
  box-shadow: var(--tw-ring-offset-shadow), var(--tw-ring-shadow), var(--tw-shadow, 0 0 #0000)
}

.duration-1000 {
  transition-duration: 1000ms
}

.\[box-shadow\:1px_3px_0px_0px_\#000\] {
  box-shadow: 1px 3px 0px 0px #000
}

.after\:absolute::after {
  content: var(--tw-content);
  position: absolute
}

.after\:left-1::after {
  content: var(--tw-content);
  left: 0.25rem
}

.after\:top-1::after {
  content: var(--tw-content);
  top: 0.25rem
}

.after\:h-10::after {
  content: var(--tw-content);
  height: 2.5rem
}

.after\:w-10::after {
  content: var(--tw-content);
  width: 2.5rem
}

.after\:rounded-full::after {
  content: var(--tw-content);
  border-radius: 9999px
}

.after\:outline-none::after {
  content: var(--tw-content);
  outline: 2px solid transparent;
  outline-offset: 2px
}

.after\:duration-300::after {
  content: var(--tw-content);
  transition-duration: 300ms
}

